/* 21-L 9B b): probe only, injected into the open page (not app/style.css).
   Sticky primary button: the wrapper stElementContainer (class st-key-<key> of the
   button) lies directly in the long stVerticalBlock of the tab panel (DOM of run 53,
   9b/kompakt_ni.json, "dom"). It sticks to the bottom edge of the window while its
   place is below the window and stands in its place when the page is scrolled past it.
   Strip under the button: window colour; line above: border colour of the blocks.
   Version 3. Version 1 (9b/v1_uzkaya_polosa/): the wrapper is as wide as the button
   (st.button width="content"), the strip covered only the button. Version 2
   (9b/v2_knopka_na_vsyu_shirinu/): width: 100% on the wrapper, the button stretched
   with it. Here the wrapper spans the column and the button keeps its own width. */
[data-testid="stVerticalBlock"] > [data-testid="stElementContainer"]:has(button[data-testid="stBaseButton-primary"]) {
    position: sticky;
    bottom: 0;
    z-index: 2;
    width: 100%;
    background-color: light-dark(#F8F8F9, #17181B);
    border-top: 1px solid light-dark(#CFD1D5, #33373E);
    padding: 12px 0;
}
[data-testid="stVerticalBlock"] > [data-testid="stElementContainer"]:has(button[data-testid="stBaseButton-primary"]) > [data-testid="stButton"] {
    width: fit-content;
}
